export const NATE_USER_ID = "00000000-0000-0000-0000-000000000999"
export const NATE_THINKING = "I am thinking..."
/** Students always see this name, whether the group is in Nate mode or Remy mode. */
export const AGENT_DISPLAY_NAME = "Remy"
/** Shown in the composer when @-mentioning the AI teammate (stored in message text). */
export const NATE_MENTION_TEXT = "@Remy"

/** Fixed welcome posted once per chat session when AI is enabled (not generated by the model). */
export const AGENT_OPENING_MESSAGE = `Hi everyone, I'm ${AGENT_DISPLAY_NAME}, your AI group member. Nice to meet you all! ${NATE_MENTION_TEXT}, to talk to me. I'm ready when you are!`

export type NateMode = 1 | 2 | 3

export function normalizeNateMode(value: number | null | undefined): NateMode {
  if (value === 2 || value === 3) return value
  return 1
}

export function mentionsNATE(message: string): boolean {
  const text = message.toLowerCase()
  return text.includes("@remy") || text.includes("@nate")
}

const FIGURE_URL = /!\[[^\]]*\]\((data:image\/(?:png|jpe?g|gif|webp);base64,[A-Za-z0-9+/=]+)\)/g

export function figureDataUrls(content: string): string[] {
  return [...content.matchAll(new RegExp(FIGURE_URL.source, "g"))].map((match) => match[1])
}

export function stripFigures(content: string): string {
  return content
    .replace(/!\[sticker:([^\]]*)\]\((?:https:\/\/[^)\s]+|\/chat-stickers\/[^)\s]+)\)/gi, (_, label: string) => `[Reaction: ${String(label).trim()}]`)
    .replace(/!\[[^\]]*\]\((?:data:image\/[^)]+|https:\/\/[^)\s]+)\)/g, "")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim()
}

